-- The store's schema on PostgreSQL: the SQLite engine's 000001 to 000025, folded into one baseline
-- (ADR 1793319634). Scripts 000002 to 000025 of this engine are therefore empty; from 000026 on,
-- every script ships for both engines under one name. The tables, columns, keys, checks and
-- indexes are SQLite's, with these translations:
--   - INTEGER PRIMARY KEY (a rowid alias) and AUTOINCREMENT: bigint GENERATED BY DEFAULT AS IDENTITY,
--     which never reuses a value, as AUTOINCREMENT promised. BY DEFAULT, so a row written with its
--     id (a copy, a test fixture) keeps it.
--   - INTEGER: bigint, the int64 every reader scans. BLOB: bytea. WITHOUT ROWID: a plain table with
--     the same primary key.
--   - TEXT: text COLLATE "C". SQLite compares text byte by byte, and orders (path order) and ranges
--     (a folder as ["dir/", "dir0")) rely on it; the database's own locale would sort otherwise.
--   - chunk_fts (FTS5, external content, kept by three triggers): a generated tsvector column on
--     chunk itself, weighted title A, breadcrumb B, tags C, body D, with a GIN index. A generated
--     column is kept by PostgreSQL on every write, as the triggers kept FTS5.
-- The tables are created in the first schema of the connection's search_path.

-- Snowball English stemming with no stop words: every word is kept, so every query word is
-- required, as SQLite's porter tokenizer does (pgstore's rag_english, under a name of its own, so the
-- two stores can share a schema).
CREATE TEXT SEARCH DICTIONARY autodoc_english_stem (TEMPLATE = snowball, Language = english);
CREATE TEXT SEARCH CONFIGURATION autodoc_english (COPY = simple);
ALTER TEXT SEARCH CONFIGURATION autodoc_english
    ALTER MAPPING FOR asciiword, asciihword, hword_asciipart, word, hword, hword_part
    WITH autodoc_english_stem;

-- Embedding providers and rankers come first: a workspace names its provider.
CREATE TABLE embedding_provider (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name       text COLLATE "C" NOT NULL UNIQUE,
  kind       text COLLATE "C" NOT NULL CHECK (kind IN ('ollama', 'ollama-cloud', 'openai')),
  base_url   text COLLATE "C" NOT NULL,
  model      text COLLATE "C" NOT NULL,
  api_key    bytea,
  created_at bigint NOT NULL,
  updated_at bigint NOT NULL,
  context    bigint NOT NULL DEFAULT 8192
);

CREATE TABLE embedding_usage (
  provider_id bigint NOT NULL REFERENCES embedding_provider(id) ON DELETE CASCADE,
  day         text COLLATE "C" NOT NULL,
  requests    bigint NOT NULL DEFAULT 0,
  texts       bigint NOT NULL DEFAULT 0,
  tokens      bigint NOT NULL DEFAULT 0,
  failures    bigint NOT NULL DEFAULT 0,
  limited     bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (provider_id, day)
);

CREATE TABLE embedding_log (
  id          bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  provider_id bigint NOT NULL REFERENCES embedding_provider(id) ON DELETE CASCADE,
  at          bigint NOT NULL,
  texts       bigint NOT NULL,
  tokens      bigint NOT NULL,
  millis      bigint NOT NULL,
  outcome     text COLLATE "C" NOT NULL
);
CREATE INDEX embedding_log_provider ON embedding_log(provider_id, id);

CREATE TABLE ranker (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name       text COLLATE "C" NOT NULL UNIQUE,
  kind       text COLLATE "C" NOT NULL CHECK (kind IN ('tei', 'rerank-api')),
  base_url   text COLLATE "C" NOT NULL,
  model      text COLLATE "C" NOT NULL DEFAULT '',
  api_key    bytea,
  created_at bigint NOT NULL,
  updated_at bigint NOT NULL
);

CREATE TABLE ranker_usage (
  ranker_id bigint NOT NULL REFERENCES ranker(id) ON DELETE CASCADE,
  day       text COLLATE "C" NOT NULL,
  requests  bigint NOT NULL DEFAULT 0,
  texts     bigint NOT NULL DEFAULT 0,
  tokens    bigint NOT NULL DEFAULT 0,
  failures  bigint NOT NULL DEFAULT 0,
  limited   bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (ranker_id, day)
);

CREATE TABLE ranker_log (
  id        bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  ranker_id bigint NOT NULL REFERENCES ranker(id) ON DELETE CASCADE,
  at        bigint NOT NULL,
  texts     bigint NOT NULL,
  tokens    bigint NOT NULL,
  millis    bigint NOT NULL,
  outcome   text COLLATE "C" NOT NULL
);
CREATE INDEX ranker_log_ranker ON ranker_log(ranker_id, id);

-- A workspace and its settings.
CREATE TABLE workspace (
  id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name              text COLLATE "C" NOT NULL UNIQUE,
  root              text COLLATE "C" NOT NULL UNIQUE,
  commit_seq        bigint NOT NULL DEFAULT 0,
  change_seq        bigint NOT NULL DEFAULT 0,
  created_at        bigint NOT NULL,
  updated_at        bigint NOT NULL,
  section_tokens    bigint,
  embedding_policy  text COLLATE "C" NOT NULL DEFAULT 'always'
                    CHECK (embedding_policy IN ('always', 'when opened', 'never')),
  include_empty     bigint NOT NULL DEFAULT 0 CHECK (include_empty IN (0, 1)),
  schema_path       text COLLATE "C",
  text_extensions   text COLLATE "C",
  provider_id       bigint REFERENCES embedding_provider(id) ON DELETE SET NULL,
  uid               text COLLATE "C",
  destination       text COLLATE "C" NOT NULL DEFAULT 'sqlite' CHECK (destination IN ('sqlite', 'postgres')),
  vector_index      text COLLATE "C" CHECK (vector_index IN ('hnsw', 'ivfflat')),
  view_args         text COLLATE "C",
  abstract_chunk    bigint NOT NULL DEFAULT 0,
  demote_superseded bigint NOT NULL DEFAULT 0,
  graph_only_set    bigint NOT NULL DEFAULT 0 CHECK (graph_only_set IN (0, 1)),
  todo_graph_only   bigint NOT NULL DEFAULT 0 CHECK (todo_graph_only IN (0, 1))
);
CREATE UNIQUE INDEX workspace_uid ON workspace (uid);

CREATE TABLE workspace_pattern (
  workspace_id bigint NOT NULL REFERENCES workspace(id) ON DELETE CASCADE,
  kind         text COLLATE "C" NOT NULL CHECK (kind IN ('include', 'exclude')),
  ord          bigint NOT NULL,
  pattern      text COLLATE "C" NOT NULL,
  PRIMARY KEY (workspace_id, kind, ord)
);

CREATE TABLE workspace_graph_only (
  workspace_id bigint NOT NULL REFERENCES workspace(id) ON DELETE CASCADE,
  ord          bigint NOT NULL,
  pattern      text COLLATE "C" NOT NULL,
  PRIMARY KEY (workspace_id, ord)
);

CREATE TABLE workspace_connection (
  workspace_id bigint NOT NULL REFERENCES workspace(id) ON DELETE CASCADE,
  role         text COLLATE "C" NOT NULL CHECK (role IN ('source', 'destination')),
  engine       text COLLATE "C" NOT NULL CHECK (engine IN ('postgres', 'sqlite')),
  dsn          bytea NOT NULL,
  schema_name  text COLLATE "C",
  updated_at   bigint NOT NULL,
  PRIMARY KEY (workspace_id, role)
);

-- The index: documents, their chunks (with the full-text vector FTS5 held), names and links.
CREATE TABLE document (
  id                bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  workspace_id      bigint NOT NULL REFERENCES workspace(id) ON DELETE CASCADE,
  path              text COLLATE "C" NOT NULL,
  version           text COLLATE "C" NOT NULL,
  active_gen        bigint NOT NULL,
  semantic_ready    bigint NOT NULL DEFAULT 0,
  title             text COLLATE "C",
  frontmatter_json  text COLLATE "C",
  frontmatter_error text COLLATE "C",
  indexer           text COLLATE "C" NOT NULL,
  indexed_at        bigint NOT NULL,
  UNIQUE (workspace_id, id),
  UNIQUE (workspace_id, path)
);

CREATE TABLE chunk (
  id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  workspace_id bigint NOT NULL,
  doc_id       bigint NOT NULL,
  hash         bytea NOT NULL,
  text_hash    bytea NOT NULL,
  gen_from     bigint NOT NULL,
  gen_to       bigint,
  ord          bigint NOT NULL,
  breadcrumb   text COLLATE "C" NOT NULL,
  body         text COLLATE "C" NOT NULL,
  title        text COLLATE "C" NOT NULL,
  tags         text COLLATE "C" NOT NULL,
  byte_start   bigint NOT NULL,
  byte_end     bigint NOT NULL,
  embed        text COLLATE "C" NOT NULL DEFAULT '',
  kind         text COLLATE "C" NOT NULL DEFAULT 'section',
  tsv          tsvector GENERATED ALWAYS AS (
      setweight(to_tsvector('autodoc_english'::regconfig, title), 'A') ||
      setweight(to_tsvector('autodoc_english'::regconfig, breadcrumb), 'B') ||
      setweight(to_tsvector('autodoc_english'::regconfig, tags), 'C') ||
      setweight(to_tsvector('autodoc_english'::regconfig, body), 'D')
  ) STORED,
  UNIQUE (workspace_id, id),
  FOREIGN KEY (workspace_id, doc_id) REFERENCES document(workspace_id, id) ON DELETE CASCADE
);
CREATE INDEX chunk_doc ON chunk(workspace_id, doc_id, gen_to);
CREATE INDEX chunk_dead ON chunk(workspace_id, gen_to) WHERE gen_to IS NOT NULL;
CREATE INDEX chunk_text ON chunk(workspace_id, text_hash);
CREATE INDEX chunk_tsv ON chunk USING gin (tsv);

CREATE TABLE doc_tag (
  workspace_id bigint NOT NULL,
  doc_id       bigint NOT NULL,
  tag          text COLLATE "C" NOT NULL,
  PRIMARY KEY (workspace_id, tag, doc_id),
  FOREIGN KEY (workspace_id, doc_id) REFERENCES document(workspace_id, id) ON DELETE CASCADE
);
CREATE INDEX doc_tag_doc ON doc_tag(workspace_id, doc_id);

CREATE TABLE doc_alias (
  workspace_id bigint NOT NULL,
  doc_id       bigint NOT NULL,
  alias        text COLLATE "C" NOT NULL,
  PRIMARY KEY (workspace_id, alias, doc_id),
  FOREIGN KEY (workspace_id, doc_id) REFERENCES document(workspace_id, id) ON DELETE CASCADE
);
CREATE INDEX doc_alias_doc ON doc_alias(workspace_id, doc_id);

CREATE TABLE doc_name (
  workspace_id bigint NOT NULL,
  name_key     text COLLATE "C" NOT NULL,
  doc_id       bigint NOT NULL,
  is_path      bigint NOT NULL,
  PRIMARY KEY (workspace_id, name_key, doc_id),
  FOREIGN KEY (workspace_id, doc_id) REFERENCES document(workspace_id, id) ON DELETE CASCADE
);
CREATE INDEX doc_name_doc ON doc_name(workspace_id, doc_id, is_path);

CREATE TABLE doc_facet (
  workspace_id bigint NOT NULL,
  doc_id       bigint NOT NULL,
  field        text COLLATE "C" NOT NULL,
  value        text COLLATE "C" NOT NULL,
  PRIMARY KEY (workspace_id, field, value, doc_id),
  FOREIGN KEY (workspace_id, doc_id) REFERENCES document(workspace_id, id) ON DELETE CASCADE
);
CREATE INDEX doc_facet_doc ON doc_facet(workspace_id, doc_id);

CREATE TABLE doc_diagnostic (
  workspace_id bigint NOT NULL,
  doc_id       bigint NOT NULL,
  ord          bigint NOT NULL,
  field        text COLLATE "C" NOT NULL,
  line         bigint NOT NULL,
  rule         text COLLATE "C" NOT NULL,
  message      text COLLATE "C" NOT NULL,
  PRIMARY KEY (workspace_id, doc_id, ord),
  FOREIGN KEY (workspace_id, doc_id) REFERENCES document(workspace_id, id) ON DELETE CASCADE
);

CREATE TABLE link (
  id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  workspace_id bigint NOT NULL,
  src_doc      bigint NOT NULL,
  gen_from     bigint NOT NULL,
  gen_to       bigint,
  raw          text COLLATE "C" NOT NULL,
  name         text COLLATE "C" NOT NULL,
  dst_doc      bigint,
  anchor       text COLLATE "C",
  kind         text COLLATE "C" NOT NULL,
  target       text COLLATE "C",
  UNIQUE (workspace_id, id),
  FOREIGN KEY (workspace_id, src_doc) REFERENCES document(workspace_id, id) ON DELETE CASCADE
);
CREATE INDEX link_name ON link(workspace_id, name);
CREATE INDEX link_src ON link(workspace_id, src_doc);
CREATE INDEX link_dst ON link(workspace_id, dst_doc);

CREATE TABLE link_key (
  workspace_id bigint NOT NULL,
  link_id      bigint NOT NULL,
  ord          bigint NOT NULL,
  key          text COLLATE "C" NOT NULL,
  PRIMARY KEY (workspace_id, link_id, ord),
  FOREIGN KEY (workspace_id, link_id) REFERENCES link(workspace_id, id) ON DELETE CASCADE
);
CREATE INDEX link_key_key ON link_key(workspace_id, key);

-- Models and their vectors.
CREATE TABLE model (
  workspace_id bigint NOT NULL REFERENCES workspace(id) ON DELETE CASCADE,
  fp           text COLLATE "C" NOT NULL,
  provider     text COLLATE "C",
  name         text COLLATE "C",
  dims         bigint,
  active       bigint NOT NULL,
  target       bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (workspace_id, fp)
);

CREATE TABLE embedding (
  workspace_id bigint NOT NULL,
  text_hash    bytea NOT NULL,
  model_fp     text COLLATE "C" NOT NULL,
  bits         bytea NOT NULL,
  f32          bytea NOT NULL,
  PRIMARY KEY (workspace_id, text_hash, model_fp),
  FOREIGN KEY (workspace_id, model_fp) REFERENCES model(workspace_id, fp) ON DELETE CASCADE
);
CREATE INDEX embedding_workspace_model_text ON embedding(workspace_id, model_fp, text_hash);

-- The indexer's queue and the change log.
CREATE TABLE index_job (
  workspace_id bigint NOT NULL REFERENCES workspace(id) ON DELETE CASCADE,
  path         text COLLATE "C" NOT NULL,
  seq          bigint NOT NULL,
  reason       text COLLATE "C",
  enqueued_at  bigint,
  attempts     bigint NOT NULL DEFAULT 0,
  last_error   text COLLATE "C",
  PRIMARY KEY (workspace_id, path)
);

CREATE TABLE change (
  workspace_id bigint NOT NULL REFERENCES workspace(id) ON DELETE CASCADE,
  seq          bigint NOT NULL,
  path         text COLLATE "C" NOT NULL,
  op           text COLLATE "C" NOT NULL,
  generation   bigint NOT NULL,
  at           bigint NOT NULL,
  PRIMARY KEY (workspace_id, seq)
);

-- Preferences and the event log.
CREATE TABLE preference (
  name       text COLLATE "C" PRIMARY KEY,
  value      text COLLATE "C" NOT NULL,
  updated_at bigint NOT NULL
);

CREATE TABLE event (
  seq       bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  kind      text COLLATE "C" NOT NULL,
  workspace text COLLATE "C" NOT NULL DEFAULT '',
  client    text COLLATE "C" NOT NULL DEFAULT '',
  detail    text COLLATE "C" NOT NULL DEFAULT '',
  at        bigint NOT NULL
);

-- The todo stores.
CREATE TABLE todo_store (
  id           text COLLATE "C" PRIMARY KEY,
  path         text COLLATE "C" NOT NULL,
  claimed      bigint NOT NULL DEFAULT 0,
  claimed_at   bigint,
  last_use     bigint,
  refreshed_at bigint,
  kb           text COLLATE "C" NOT NULL DEFAULT '',
  released_at  bigint
);

CREATE TABLE todo_root (
  root          text COLLATE "C" PRIMARY KEY,
  override      text COLLATE "C" NOT NULL DEFAULT '',
  registered    bigint,
  kb_root       text COLLATE "C" NOT NULL DEFAULT '',
  last_resolved bigint
);

CREATE TABLE todo_var (
  name  text COLLATE "C" PRIMARY KEY,
  value text COLLATE "C" NOT NULL
);

CREATE TABLE todo_change (
  seq        bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  store      text COLLATE "C" NOT NULL,
  id         text COLLATE "C" NOT NULL DEFAULT '',
  kind       text COLLATE "C" NOT NULL,
  op         text COLLATE "C" NOT NULL,
  from_value text COLLATE "C" NOT NULL DEFAULT '',
  to_value   text COLLATE "C" NOT NULL DEFAULT '',
  fields     text COLLATE "C",
  reason     text COLLATE "C" NOT NULL DEFAULT '',
  hand       bigint NOT NULL DEFAULT 0,
  from_path  text COLLATE "C" NOT NULL DEFAULT '',
  to_path    text COLLATE "C" NOT NULL DEFAULT '',
  from_rev   text COLLATE "C" NOT NULL DEFAULT '',
  to_rev     text COLLATE "C" NOT NULL DEFAULT '',
  state      text COLLATE "C" NOT NULL CHECK (state IN ('pending', 'staged', 'committed')),
  at         bigint,
  scope      text COLLATE "C" NOT NULL DEFAULT ''
);
CREATE INDEX todo_change_store ON todo_change (store, state, seq);

CREATE TABLE todo_snapshot (
  store    text COLLATE "C" NOT NULL,
  path     text COLLATE "C" NOT NULL,
  id       text COLLATE "C" NOT NULL,
  rev      text COLLATE "C" NOT NULL,
  status   text COLLATE "C" NOT NULL,
  assignee text COLLATE "C" NOT NULL DEFAULT '',
  fields   text COLLATE "C",
  scope    text COLLATE "C" NOT NULL DEFAULT '',
  PRIMARY KEY (store, path)
);
CREATE INDEX todo_snapshot_id ON todo_snapshot (store, id, assignee, scope);

CREATE TABLE todo_consumer (
  store        text COLLATE "C" NOT NULL,
  name         text COLLATE "C" NOT NULL,
  acked_seq    bigint NOT NULL DEFAULT 0,
  seen_at      bigint,
  unregistered bigint NOT NULL DEFAULT 0,
  resync_seq   bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (store, name)
);

CREATE TABLE todo_store_var (
  store text COLLATE "C" NOT NULL,
  name  text COLLATE "C" NOT NULL,
  value text COLLATE "C" NOT NULL,
  PRIMARY KEY (store, name)
);

CREATE TABLE todo_workspace_var (
  kb    text COLLATE "C" NOT NULL,
  name  text COLLATE "C" NOT NULL,
  value text COLLATE "C" NOT NULL,
  PRIMARY KEY (kb, name)
);
